/**
 ******************************************************************************
 * @file           : main.c
 * @author         : Auto-generated by STM32CubeIDE for Visual Studio Code Extension
 * @brief          : Aprendizaje de GPIO e interrupciones externas con CMSIS.
 ******************************************************************************
 * Objetivo: detectar la pulsación del botón de la NUCLEO-F411RE usando PC13.
 * La placa tiene un pull-up externo: sin pulsar, el pin está en alto (1);
 * al pulsar, el botón lo conecta a tierra y pasa a bajo (0).
 * Ese cambio de 1 a 0 se llama flanco de bajada.
 *
 * Recorrido de la señal:
 * PC13 -> selección del puerto en SYSCFG -> EXTI13 -> NVIC -> ISR.
 * EXTI detecta el cambio; NVIC gestiona la solicitud; la ISR lo atiende.
 *
 * Estado actual: main() inicializa GPIO y EXTI antes de entrar al bucle.
 * La ISR comprueba la bandera de EXTI13 y limpia la solicitud pendiente.
 * Pendiente: registrar el evento del botón y procesar una acción en main().
 *
 ******************************************************************************
 */

#include <stdint.h>       // Tipos de tamaño fijo, como uint32_t (32 bits).
#include <stm32f411xe.h>  // Registros, máscaras y números de IRQ del STM32F411.
#include <stm32f4xx.h>    // Encabezado de la familia STM32F4.

/*
 * Bandera de software: guardará un aviso del botón para que main() lo procese.
 * Es una variable en RAM; no es el registro PR ni el nivel eléctrico de PC13.
 * Al estar fuera de las funciones, tanto la ISR como main() pueden acceder a ella.
 *
 * uint32_t: entero sin signo de 32 bits. Usaremos 0 = sin evento y 1 = evento pendiente.
 * = 0U: comienza sin eventos pendientes; U indica que el literal es sin signo.
 * volatile: exige realizar las lecturas y escrituras de esta variable, porque
 * la ISR puede modificarla mientras main() ejecuta otras instrucciones.
 * Así el compilador no trata su valor como si permaneciera fijo entre consultas.
 *
 * Pendiente: la ISR la pondrá en 1; main() leerá y consumirá ese aviso.
 * El hardware no cambia esta variable automáticamente: lo hará nuestro código.
 */
volatile uint32_t evento_boton = 0U;

/*
 * Prototipos: anuncian al compilador el nombre y la forma de cada función.
 * void antes del nombre: la función no devuelve un valor.
 * (void): la función no recibe argumentos.
 */
void init_GPIO(void);
void init_EXTI13(void);
void EXTI15_10_IRQHandler(void); // ISR de la línea EXTI13, compartida con EXTI10 a EXTI15.

int main(void)
{
    init_GPIO();
    init_EXTI13();


    // Las funciones anteriores configuran el hardware una vez al iniciar.
    // El procesador ejecuta la ISR automáticamente al atender su interrupción.
    // El bucle se repite indefinidamente; por ahora no ejecuta ninguna acción.
	while(1){

         if (evento_boton != 0U) {
            evento_boton = 0U; //bajamos la bandera.
            GPIOA->ODR  ^= (1U <<5U); // Alterna el LED: si está encendido, lo apaga; si está apagado, lo enciende.
    }

    }

    
}


void init_GPIO(void)
{
    /*
     * CMSIS da nombres a los registros y a sus máscaras de bits.
     * -> accede a un registro del periférico, por ejemplo RCC->AHB1ENR.
     * Una máscara tiene unos en las posiciones que queremos seleccionar.
     * registro |= máscara: pone esos bits en 1 y conserva los demás.
     * registro &= ~máscara: pone esos bits en 0 y conserva los demás.
     * ~ invierte la máscara: sus unos pasan a ceros y sus ceros a unos.
     */

    // RCC controla los relojes. AHB1ENR habilita periféricos del bus AHB1.
    // GPIOCEN_Msk selecciona el bit 2, que controla el reloj de GPIOC.
    // Seguimos la secuencia de clase: apagar y luego encender ese reloj.
    // Apagar el reloj no reinicia la configuración de los registros de GPIOC.
    RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOCEN_Msk); // Bit 2 = 0: reloj deshabilitado.
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN_Msk; // Bit 2 = 1: reloj habilitado.

    // MODER asigna dos bits de modo a cada pin; PC13 ocupa los bits 27 y 26.
    // La máscara selecciona ambos. Al dejarlos en 00, PC13 queda como entrada.
    GPIOC->MODER &= ~(GPIO_MODER_MODE13_Msk);

    // PUPDR también usa dos bits por pin; 00 desactiva las resistencias internas.
    // El pull-up externo de la placa mantiene PC13 en alto sin pulsar el botón.
    // Esta instrucción no desconecta esa resistencia externa.
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD13_Msk);

    //Habilitamos el pin A5 para encender un led.
    RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOAEN); // Limpiamos
    RCC->AHB1ENR |= (RCC_AHB1ENR_GPIOAEN); //Activamos la señal de reloj

    GPIOA->MODER &= ~(GPIO_MODER_MODER5_Msk); //borramos la posición para limpiar
    GPIOA->MODER |= (GPIO_MODER_MODE5_0); //activamos como salida (01)
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT5); //limpiamos posición
    GPIOA->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED5_Msk); //Baja velocidad
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPDR5); //ni pull ni dwon.
    GPIOA->ODR |= (1U << 5U); // PA5 = 1: LED encendido.


}

void init_EXTI13(void)
{
    // SYSCFG selecciona qué puerto GPIO alimenta cada línea EXTI.
    // Su reloj se controla en APB2ENR: SYSCFGEN_Msk selecciona el bit 14.
    // Lo ponemos en 1 para poder configurar SYSCFG.
    // En este microcontrolador EXTI no tiene un reloj separado que habilitar.
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN_Msk;

    // El número del pin determina la línea: pin 13 -> EXTI13.
    // Hay que elegir el puerto: PA13, PB13, PC13, etc. comparten esa línea.
    // Solo un puerto puede alimentar EXTI13 a la vez.
    // EXTICR4 contiene las líneas 12 a 15; en C es EXTICR[3], contando desde 0.
    // Dentro de ese registro, el campo de EXTI13 ocupa los bits 7 a 4.

    // Primero dejamos sus cuatro bits en 0000, conservando los otros campos.
    // Esto elimina una selección anterior: |= por sí solo no puede borrar bits.
    SYSCFG->EXTICR[3] &= ~(SYSCFG_EXTICR4_EXTI13_Msk);

    // La constante terminada en _PC contiene el código 0010 del puerto C,
    // ya desplazado a los bits 7 a 4. Ahora la ruta seleccionada es PC13 -> EXTI13.
    SYSCFG->EXTICR[3] |= SYSCFG_EXTICR4_EXTI13_PC;

    // FTSR selecciona qué líneas detectan flancos de bajada (1 -> 0).
    // RTSR selecciona qué líneas detectan flancos de subida (0 -> 1).
    // TR13_Msk selecciona el bit 13: lo ponemos en 1 para detectar ese cambio.
    EXTI->RTSR &= ~EXTI_RTSR_TR13_Msk; // Subida deshabilitada.
    EXTI->FTSR |= EXTI_FTSR_TR13_Msk; // Bajada habilitada.

    EXTI->PR = EXTI_PR_PR13_Msk; // Limpiar la bandera de solicitud pendiente de EXTI13.


    // IMR permite o bloquea las solicitudes de interrupción de cada línea.
    // Bit 13 = 1: EXTI13 puede enviar una solicitud al NVIC.
    // Detectar el flanco y permitir la solicitud son dos configuraciones distintas.
    EXTI->IMR |= EXTI_IMR_MR13_Msk;

    // NVIC es el controlador de interrupciones del procesador.
    // Cada línea EXTI tiene un número de IRQ asignado. EXTI10 a EXTI15 comparten el mismo.
    // NVIC_EnableIRQ() habilita la línea de interrupción en el NVIC.
    NVIC_EnableIRQ(EXTI15_10_IRQn);
}

void EXTI15_10_IRQHandler(void)
{
    /*
     * ISR significa Interrupt Service Routine: rutina de servicio de interrupción.
     * Esta función atiende la entrada que comparten las líneas EXTI10 a EXTI15.
     *
     * ¿Cómo llegamos aquí?
     * 1. PC13 pasa de alto a bajo: EXTI detecta el flanco configurado en FTSR.
     * 2. El hardware pone la bandera PR13 en 1: hay una solicitud pendiente.
     * 3. Con EXTI13 habilitada en IMR, la solicitud llega al NVIC.
     * 4. Cuando el procesador puede atenderla, guarda el contexto necesario
     *    para regresar y ejecuta esta función mediante la tabla de vectores.
     * main() no necesita llamar a esta función ni revisar continuamente PC13.
     *
     * Como EXTI10 a EXTI15 comparten la misma ISR, entrar aquí no demuestra
     * por sí solo que EXTI13 fue el origen: debemos comprobar su bandera.
     */

    /*
     * COMPROBAR LA BANDERA
     * EXTI->PR accede al registro Pending Register (solicitudes pendientes).
     * Al leer PR13: 0 = ninguna solicitud pendiente; 1 = solicitud pendiente.
     * PR recuerda el evento detectado; no es el nivel actual del botón.
     * Para conocer el nivel actual del pin se leería GPIOC->IDR.
     *
     * EXTI_PR_PR13_Msk equivale a (1U << 13): 0x00002000, o 8192 en decimal.
     * La máscara tiene un 1 en el bit 13 y ceros en las demás posiciones.
     * & hace un AND bit a bit: deja pasar solamente el bit seleccionado.
     * Esta expresión lee PR y calcula un resultado; no escribe en el registro.
     *
     * PR13 = 0 -> (PR & máscara) vale 0      -> el if omite el bloque.
     * PR13 = 1 -> (PR & máscara) vale 0x2000 -> el if ejecuta el bloque.
     * En C, el if considera verdadero cualquier resultado distinto de cero;
     * por eso no necesitamos que el resultado sea exactamente 1.
     */
    if (EXTI->PR & EXTI_PR_PR13_Msk) {
        // Aquí sabemos que EXTI13 tiene una solicitud pendiente.
        // Pendiente: registrar el evento del botón para procesarlo en main().
        // Mantendremos corta la ISR; por ahora solo se realiza la limpieza de PR.

        /*
         * LIMPIAR LA BANDERA
         * PR no se comporta como una variable normal de RAM.
         * Sus banderas se borran escribiendo 1: write-one-to-clear (W1C).
         * Escribir 1 en PR13 ordena al hardware dejar esa bandera en 0.
         * Escribir 0 en los otros bits conserva el estado de sus banderas.
         *
         * Limpiar PR13 retira la solicitud que estamos atendiendo. Si la dejamos
         * pendiente, puede provocar que el procesador vuelva a entrar en la ISR.
         * Esta limpieza no cambia el nivel eléctrico de PC13 ni deshabilita EXTI13.
         */
        EXTI->PR = EXTI_PR_PR13_Msk;
        evento_boton = 1U;

    }

    // Al terminar la ISR, el procesador restaura el contexto y continúa la
    // ejecución interrumpida, salvo que deba atender otra interrupción primero.
}

